(32111, 'John 1:37', 'John', 1, 37, 'د یحیی دوو شاګردانو دا خبره واورېدله او عیسی پسې روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_37.mp3', '', 1761754199, 1761754199),
(32112, 'John 1:38', 'John', 1, 38, 'عیسی شاته وکتل او ویې لیدل چې هغوی هغه پسې روان دي نو پوښتنه یې ترې وکړه: «تاسو څه شي پسې ګرځئ؟» هغوی پوښتنه وکړه: «ربي ته چېرته اوسېږې؟» (د ربي معنی استاذ دی.)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_38.mp3', '', 1761754199, 1761754199),
(32113, 'John 1:39', 'John', 1, 39, 'عیسی وویل: «راشئ او وګورئ.» دا شاوخوا د ماسپښین څلور بجې وې نو هغوی د هغه سره لاړل او ویې لیدل چې هغه چېرته اوسېده او پاتې ورځ یې د هغه سره تېره کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_39.mp3', '', 1761754199, 1761754199),
(32114, 'John 1:40', 'John', 1, 40, 'د هغو دوه تنو څخه چې د یحیی د خبرو له اورېدلو وروسته عیسی پسې روان شو، یو یې د شمعون پطروس ورور اندریاس ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_40.mp3', '', 1761754199, 1761754199),
(32115, 'John 1:41', 'John', 1, 41, 'لومړنی کار چې هغه وکړ، هغه دا ؤ چې هغه خپل ورور شمعون پیدا کړ او هغه ته یې وویل: «مونږ مسیح موندلی دی،» چې د مسېح معنی ده وعده شوی پاچا.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_41.mp3', '', 1761754199, 1761754199),
(32116, 'John 1:42', 'John', 1, 42, 'نو اندریاس شمعون عیسی ته راوست. عیسی هغه ته وکتل او ویې ویل: «ته د یوحنا زوی شمعون یې، خو له دې وروسته به ته د کیفا په نوم یادېږې.» (د کیفا معنی پطروس دی چې معنی یې تیږه ده.) عیسی فیلیپوس او نتناییل ته بلنه ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_42.mp3', '', 1761754199, 1761754199),
(32117, 'John 1:43', 'John', 1, 43, 'بله ورځ عیسی دا پرېکړه وکړه چې جلیل ته لاړ شي. په لاره کې هغه فیلیپوس پیدا کړ او ورته یې وویل: «ما پسې راځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_43.mp3', '', 1761754199, 1761754199),
(32118, 'John 1:44', 'John', 1, 44, 'فیلیپوس د اندریاس او پطروس په شان د بیت‌صیدا ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_44.mp3', '', 1761754199, 1761754199),
(32119, 'John 1:45', 'John', 1, 45, 'فیلیپوس نتناییل راپیدا کړ او ورته ویې ویل: «مونږ هغه کس پیدا کړ چې موسی د شریعت په کتاب کې لیکلي او همدارنګه پیغمبرانو هم د هغه په هکله لیکنې کړي دي. هغه عیسی دی چې د ناصرې د ښار څخه دی او د یوسف زوی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_45.mp3', '', 1761754199, 1761754199),
(32120, 'John 1:46', 'John', 1, 46, 'نتناییل د هغه نه پوښتنه وکړه: «ایا په ناصرې کې هم ښه شی پیدا کېدای شي؟» فیلیپوس ځواب ورکړ: «راشه او وګوره.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_46.mp3', '', 1761754199, 1761754199),
(32121, 'John 1:47', 'John', 1, 47, 'کله چې عیسی ولیدل چې نتناییل د هغه خواته راروان دی نو د هغه په هکله یې وویل: «دا سړی اصلي اسراییلی دی او په هغه کې هېڅ کومه ټګي نشته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_47.mp3', '', 1761754199, 1761754199),
(32122, 'John 1:48', 'John', 1, 48, 'نتناییل پوښتنه وکړه: «ته ما څنګه پېژنې؟» عیسی ځواب ورکړ: «مخکې له دې چې فیلیپوس تاته غږ وکړي ماته ولیدلې چې د انځر د ونې لاندې وې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_48.mp3', '', 1761754199, 1761754199),
(32123, 'John 1:49', 'John', 1, 49, 'نتناییل وویل: «استاذه! ته د خدای زوی یې! ته د اسراییلو پاچا یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_49.mp3', '', 1761754199, 1761754199),
(32124, 'John 1:50', 'John', 1, 50, 'عیسی وویل: «ایا تا په دې خاطر ایمان راوړ چې ما درته وویل چې ته مې د انځر د ونې لاندې ولیدلې؟ ته به د دې نه هم لوی لوی کارونه ووینې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_50.mp3', '', 1761754199, 1761754199),
(32125, 'John 1:51', 'John', 1, 51, 'بیا یې هغه ته وویل: «په یقین سره زه تاسو ته دا وایم چې تاسو به ووینئ چې اسمان به پرانیستل شي او د خدای فرښتې به د انسان د زوی په مرسته اسمان ته خېژي او راښکته کیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john1_verse_51.mp3', '', 1761754199, 1761754199),
(32126, 'Jude 1:1', 'Jude', 1, 1, 'دا لیک د یهودا له خوا چې د عیسی مسیح خدمتګار او د یعقوب ورور دی، هغو خلکو ته لیکل شوی دی چې د پلار خدای له خوا رابلل شوي دي او مینه ورسره کوي او د عیسی مسیح په وسیله خوندي ساتل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_1.mp3', '', 1761754199, 1761754199),
(32127, 'Jude 1:2', 'Jude', 1, 2, 'رحم، سلامتي او مینه دې په تاسو کې زیاته شي. د دروغجنو استاذانو په هکله تعلیم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_2.mp3', '', 1761754199, 1761754199),
(32128, 'Jude 1:3', 'Jude', 1, 3, 'ګرانو دوستانو! ما ډېر غوښتل چې تاسو ته د هغه خلاصون په هکله ولیکم چې مونږ ټول په کې شریک یو، خو دا مې ضروري وګڼله چې تاسو وهڅوم چې د هغه ایمان په خاطر چې خدای یوځل او د تل دپاره خپلو سپېڅلو خلکو ته ورکړی دی، هلې‌ځلې وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_3.mp3', '', 1761754199, 1761754199),
(32129, 'Jude 1:4', 'Jude', 1, 4, 'زه تاسو ته د دې دپاره وایم چې ځینې بې‌دینه خلک چې د غلطې عقیدې په هکله تعلیم ورکوي، په پټه په مونږ کې راننوتلي دي. دا هغه خلک دي چې ډېر پخوا د خدای په کلام کې هغوی ته د سزا ورکولو په هکله لیکل شوي دي. هغوی زمونږ د خدای فضل په غلطه تعبیروي، ترڅو د خپلو نفساني غوښتنو د پوره کولو دپاره بهانه جوړه کړي او زمونږ د یوازېني بادار او څښتن عیسی مسیح څخه انکار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_4.mp3', '', 1761754199, 1761754199),
(32130, 'Jude 1:5', 'Jude', 1, 5, 'که څه هم تاسو لا د مخکې نه له دې څخه خبر یئ، خو زه غواړم تاسو ته در په یاد کړم چې څښتن څنګه د اسراییلو خلک د مصر څخه راوویستل، خو وروسته یې هغه خلک تباه کړل چې ایمان یې رانه ووړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_5.mp3', '', 1761754199, 1761754199),
(32131, 'Jude 1:6', 'Jude', 1, 6, 'همدارنګه هغه فرښتې چې خپل مقام یې ونه ساته او خپل اصلي ځای یې پرېښود، خدای هغوی په تورو تیارو کې په تلپاتې زنځیرونو وتړلې او د قیامت تر ورځې پورې به یې چې سزا به ورته ورکوي، هلته ساتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_6.mp3', '', 1761754199, 1761754199),
(32132, 'Jude 1:7', 'Jude', 1, 7, 'په همدې ډول د سدوم او عموره او د هغه شاوخوا ښارونه چې خلک یې د هغو فرښتو په شان په جنسي بد‌اخلاقۍ او ناروا غوښتنو اخته شول او اوس ورته د عبرت په توګه په تلپاتې اور کې سزا ورکول کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_7.mp3', '', 1761754199, 1761754199),
(32133, 'Jude 1:8', 'Jude', 1, 8, 'همدارنګه دا خلک داسې رویاګانې ویني چې هغوی دې ته مجبوروي چې خپل بدنونه ناپاکه کړي، د خدای واک او اختیار نه مني او جلالي موجوداتو ته بد رد وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_8.mp3', '', 1761754199, 1761754199),
(32134, 'Jude 1:9', 'Jude', 1, 9, 'حتی میکاییل چې د ټولو فرښتو مشره ده هغې هم کله چې د شیطان سره د موسی د مړي په هکله بحث کاوه، خپل ځان ته دا حق ورنه کړ چې په بدو خبرو هغه محکوم کړي بلکې ویې ویل: «څښتن دې تاته سزا درکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_9.mp3', '', 1761754199, 1761754199),
(32135, 'Jude 1:10', 'Jude', 1, 10, 'خو دا خلک هغو شیانو ته چې پرې نه پوهیږي بد رد وایي او کله چې هغوی د بې‌شعوره ځناورو په شان عمل کوي او بې له دې چې فکر وکړي دا کارونه کوي، دا شیان د هغوی د تباهۍ سبب ګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_10.mp3', '', 1761754199, 1761754199),
(32136, 'Jude 1:11', 'Jude', 1, 11, 'افسوس د هغوی په حال! ځکه چې هغوی په هغه لاره روان شول چې قاین ورباندې روان ؤ. هغوی د پیسو په خاطر د بلعام په شان بې‌لارې شول او د قورح په شان یې سرکښي وکړه او د هغه په شان هلاک شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_11.mp3', '', 1761754199, 1761754199),
(32137, 'Jude 1:12', 'Jude', 1, 12, 'هغوی ستاسو د ملګرتیا مېلمستیاوې خرابوي، ځکه چې په بې‌شرمۍ سره خوري او څښي او یوازې د خپلو ځانونو په فکر کې دي. هغوی د بې‌بارانه ورېځو په شان دي چې بادونه یې ځغلوي. هغوی د مني بې‌مېوې ونې دي چې له بېخه ویستل شوې او بیخي مړې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_12.mp3', '', 1761754199, 1761754199),
(32138, 'Jude 1:13', 'Jude', 1, 13, 'هغوی د بحیرې د هغو توفاني څپو په شان دي چې د شرم نه ډک کارونه یې لکه د ځګونو په شان د سیند په مخ راښکاره کیږي. هغوی د سرګردانه ستورو په شان دي او خدای د هغوی دپاره یو داسې ځای ساتلی دی چې هلته تل ترتله توره تیاره وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_13.mp3', '', 1761754199, 1761754199),
(32139, 'Jude 1:14', 'Jude', 1, 14, 'خنوخ چې د آدم څخه وروسته اووم نسل ؤ، د دې خلکو په هکله پېشګویي وکړه او ویلي یې دي: «ګورئ، څښتن به د خپلو زرګونو فرښتو سره راځي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_14.mp3', '', 1761754199, 1761754199),
(32140, 'Jude 1:15', 'Jude', 1, 15, 'چې د ټولو خلکو په هکله قضاوت وکړي او هغو بې‌دینه خلکو ته د هغوی د بدو کارونو له امله چې کړي یې دي، سزا ورکړي. څښتن به دې بې‌دینه ګناهکارانو ته د هغو سختو خبرو سزا ورکړي چې د څښتن په وړاندې یې کړي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_15.mp3', '', 1761754199, 1761754199),
(32141, 'Jude 1:16', 'Jude', 1, 16, 'دا خلک تل ګوریږي او شکایتونه کوي او خپلو بدو غوښتنو پسې ګرځي. هغوی د خپلو ځانونو په هکله غټې غټې خبرې کوي او د خپلې ګټې دپاره نورو ته غوړه‌مالي کوي. خبرداری او لارښوونې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_16.mp3', '', 1761754199, 1761754199),
(32142, 'Jude 1:17', 'Jude', 1, 17, 'خو ګرانو دوستانو! تاسو باید زمونږ د څښتن عیسی مسیح د رسولانو هغه خبرې چې مخکې یې کړې دي در په یاد کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_17.mp3', '', 1761754199, 1761754199),
(32143, 'Jude 1:18', 'Jude', 1, 18, 'هغوی تاسو ته ویلي وو چې په اخره زمانه کې به داسې خلک پیدا شي چې په تاسو به ملنډې وهي او د خپلو بدو غوښتنو پسې به ګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_18.mp3', '', 1761754199, 1761754199),
(32144, 'Jude 1:19', 'Jude', 1, 19, 'دا خلک ستاسو په منځ کې بې‌اتفاقي راپیدا کوي، هغوی نفساني دي او روح القدس په کې نشته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_19.mp3', '', 1761754199, 1761754199),
(32145, 'Jude 1:20', 'Jude', 1, 20, 'خو ګرانو دوستانو! په خپل سپېڅلي ایمان کې ټینګ اوسئ، د روح القدس د قدرت په وسیله دعا کوئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_20.mp3', '', 1761754199, 1761754199),
(32146, 'Jude 1:21', 'Jude', 1, 21, 'خپل ځانونه د خدای په مینه کې ټینګ وساتئ او زمونږ د څښتن عیسی مسیح د رحم په تمه اوسئ چې تاسو ته تلپاتې ژوندون درکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_21.mp3', '', 1761754199, 1761754199),
(32147, 'Jude 1:22', 'Jude', 1, 22, 'د هغو خلکو په اړه چې شک لري، زړه سواندي اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_22.mp3', '', 1761754199, 1761754199),
(32148, 'Jude 1:23', 'Jude', 1, 23, 'نور خلک د اور د لمبو نه راوباسئ او ویې ژغورئ. د خدای څخه په وېرې سره په نورو خلکو باندې رحم کوئ او حتی له هغو کالیو څخه چې د جنسي ګناهونو داغ ورباندې لګېدلی وي، کرکه کوئ. خدای ته د ستاینې دعا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_23.mp3', '', 1761754199, 1761754199),
(32149, 'Jude 1:24', 'Jude', 1, 24, 'اوس هغه چاته چې کولای شي تاسو د تېروتنې څخه وساتي او بې‌عیبه او په ډېرې خوشحالۍ سره مو خپل د جلال څخه ډک حضور ته راولي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_24.mp3', '', 1761754199, 1761754199),
(32150, 'Jude 1:25', 'Jude', 1, 25, 'یعنې واحد خدای ته دې چې زمونږ د څښتن عیسی مسیح په وسیله زمونږ خلاصوونکی دی، جلال، لویي، قدرت او واک او اختیار وي، له ازله، اوس او تل ترتله! امین!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/jude1_verse_25.mp3', '', 1761754199, 1761754199),
(32151, 'Revelation 15:1', 'Revelation', 15, 1, 'بیا ما په اسمان کې یوه بله لویه او حیرانوونکې نښه ولیدله. هلته اووه فرښتې وې چې اووه بلاګانې ورسره وې. دا وروستنۍ بلاګانې وې، ځکه چې په دې سره د خدای قهر او غضب پای ته رسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_1.mp3', '', 1761754199, 1761754199),
(32152, 'Revelation 15:2', 'Revelation', 15, 2, 'ما د ښیښې په شان بحر ولیده چې اور ورسره یوځای ؤ. هلته مې هغه خلک ولیدل چې په ځناور او د هغه په مجسمې او د هغه د نوم په شمېرې باندې بریالي شوي وو. هغوی د ښیښې د بحر تر‌څنګ ولاړ وو او په لاسونو کې یې هغه چنګونه وو چې خدای ورته ورکړي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_2.mp3', '', 1761754199, 1761754199),
(32153, 'Revelation 15:3', 'Revelation', 15, 3, 'هغوی د خدای د خدمتګار موسی سندره او د وري سندره ویله: ای څښتنه، ای مطلق قادره خدایه! څومره لوی او عجیبه دي ستا کارونه عادلانه دي او رښتینې د ستا لارې ای د قومونو پاچا!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_3.mp3', '', 1761754199, 1761754199),
(32154, 'Revelation 15:4', 'Revelation', 15, 4, 'څوک دی چې ونه وېریږي ستا نه، ای څښتنه او ستا د نوم ثنا او صفت ونه کړي؟ ځکه یوازې ته یې چې سپېڅلی یې رابه شي ټول قومونه او ستا عبادت به وکړي ځکه لیدلي ټولو ستا عادلانه کارونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_4.mp3', '', 1761754199, 1761754199),
(32155, 'Revelation 15:5', 'Revelation', 15, 5, 'له دې نه وروسته مې ولیدل چې د خدای کور یعنې سپېڅلې خېمه په اسمان کې پرانیستل شوه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_5.mp3', '', 1761754199, 1761754199),
(32156, 'Revelation 15:6', 'Revelation', 15, 6, 'او د هغې نه اووه فرښتې د اوو بلاګانو سره راووتلې چې پاک او ځلېدونکي د کتان کالي یې اغوستي وو او د سرو زرو پټۍ یې د خپلو سینو نه تاوې کړې وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_6.mp3', '', 1761754199, 1761754199),
(32157, 'Revelation 15:7', 'Revelation', 15, 7, 'بیا د هغو څلورو اسماني موجوداتو څخه یو یې هغو اوو فرښتو ته د سرو زرو اووه جامونه ورکړل چې هغه د خدای د قهر او غضب څخه ډک وو، یعنې هغه خدای چې تل ترتله به ژوندی وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_7.mp3', '', 1761754199, 1761754199),
(32158, 'Revelation 15:8', 'Revelation', 15, 8, 'بیا د خدای کور د خدای د جلال او قدرت د لوګي څخه ډک شو او تر هغې پورې هېڅوک ورننوتلی نه شو، ترڅو چې د هغو اوو فرښتو اووه بلاګانې پای ته نه وې رسېدلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation15_verse_8.mp3', '', 1761754199, 1761754199),
(32159, 'Acts 16:1', 'Acts', 16, 1, 'پولوس دربې او لسترې ته ورسېده او په لستره کې یې ولیدل چې د تیموتاوس په نوم یو ایماندار اوسېده چې مور یې یهودۍ ایمانداره وه، خو پلار یې یوناني ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_1.mp3', '', 1761754199, 1761754199),
