(32191, 'Acts 16:33', 'Acts', 16, 33, 'د شپې په هماغه ساعت د زندان مشر هغوی بوتلل او د هغوی زخمونه یې ووینځل او سمدلاسه هغه او د هغه ټولې کورنۍ ته د تعمید غسل ورکړل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_33.mp3', '', 1761754199, 1761754199),
(32192, 'Acts 16:34', 'Acts', 16, 34, 'بیا هغه پولوس او سیلاس خپل کور ته راوستل او هغوی ته یې ډوډۍ راوړه. په دې خاطر چې هغه او ټولې کورنۍ یې په خدای باندې ایمان راوړ، نو ډېر خوشحاله شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_34.mp3', '', 1761754199, 1761754199),
(32193, 'Acts 16:35', 'Acts', 16, 35, 'کله چې سهار شو، نو رومي مامورینو خپل د پولیسو منصبداران د زندان مشر ته ورولېږل او امر یې ورته وکړ: «هغه سړي پرېږدئ چې لاړ شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_35.mp3', '', 1761754199, 1761754199),
(32194, 'Acts 16:36', 'Acts', 16, 36, 'نو د زندان مشر پولوس ته وویل: «رومي مامورینو امر کړی چې ته او سیلاس به ازاد شئ. نو اوس تاسو کولای شئ چې راووځئ او په خیر لاړ شئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_36.mp3', '', 1761754199, 1761754199),
(32195, 'Acts 16:37', 'Acts', 16, 37, 'خو پولوس د پولیسو منصبدارانو ته وویل: «سره له دې چې مونږ رومي تابعیت لرو، خو بیاهم هغو خلکو مونږ بې له کومې محاکمې څخه د ټولو خلکو په مخکې ووهلو او په زندان کې یې واچولو او اوس غواړي مونږ په پټه وباسي؟ نه، پرېږده چې هغوی خپله راشي او مونږ وباسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_37.mp3', '', 1761754199, 1761754199),
(32196, 'Acts 16:38', 'Acts', 16, 38, 'د پولیسو منصبدارانو دا خبرې رومي مامورینو ته ورسولې او کله چې هغوی خبر شول چې پولوس او سیلاس رومیان دي، نو ووېرېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_38.mp3', '', 1761754199, 1761754199),
(32197, 'Acts 16:39', 'Acts', 16, 39, 'او راغلل او د هغوی څخه یې بخښنه وغوښتله او هغوی یې د زندان څخه راوویستل او غوښتنه یې ورڅخه وکړه چې د ښار نه لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_39.mp3', '', 1761754199, 1761754199),
(32198, 'Acts 16:40', 'Acts', 16, 40, 'نو پولوس او سیلاس د زندان څخه ووتل او د لیدیه کور ته لاړل او هلته یې د ایماندارانو سره ولیدل او یوځل بیا یې هغوی ته تسلي ورکړه او بیا لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts16_verse_40.mp3', '', 1761754199, 1761754199),
(32199, 'Acts 21:1', 'Acts', 21, 1, 'مونږ د افسیسانو د مشرانو سره خدای پاماني وکړه او له هغه ځای څخه روان شولو او په کشتۍ کې مخامخ د کاس جزیرې ته لاړو. په بله ورځ د رودوس جزیرې ته ورسېدلو او له هغه ځای څخه د پاترا د ښار بندر ته لاړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_1.mp3', '', 1761754199, 1761754199),
(32200, 'Acts 21:2', 'Acts', 21, 2, 'په هغه ځای کې مونږ یوه کشتۍ پیدا کړه چې فنیقیې ته روانه وه، نو مونږ په کې سپاره شولو او لاړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_2.mp3', '', 1761754199, 1761754199),
(32201, 'Acts 21:3', 'Acts', 21, 3, 'کله چې قبرس د لېرې نه ښکاره شو، نو مونږ د هغه د جنوب خوا څخه تېر شولو او د سوریې خواته روان شولو او د صور د ښار په بندر کې ښکته شولو، ځکه چې هلته یې د کشتۍ څخه بار ښکته کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_3.mp3', '', 1761754199, 1761754199),
(32202, 'Acts 21:4', 'Acts', 21, 4, 'په هغه ځای کې مو ایمانداران پیدا کړل او یوه هفته د هغوی سره پاتې شولو. هغوی د روح القدس په لارښوونه پولوس ته وویل چې اورشلیم ته لاړ نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_4.mp3', '', 1761754199, 1761754199),
(32203, 'Acts 21:5', 'Acts', 21, 5, 'خو کله چې هفته پوره شوه، نو مونږ بیا په سفر روان شولو. هغوی ټول د خپلو ښځو او ماشومانو سره زمونږ سره ملګري شول او د ښار څخه ووتلو او د بحیرې په غاړه په ګونډو شولو او دعا مو وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_5.mp3', '', 1761754199, 1761754199),
(32204, 'Acts 21:6', 'Acts', 21, 6, 'بیا مو یو د بل سره خدای پاماني وکړه. مونږ په کشتۍ کې سپاره شو او هغوی بېرته خپلو کورونو ته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_6.mp3', '', 1761754199, 1761754199),
(32205, 'Acts 21:7', 'Acts', 21, 7, 'مونږ په بحیره کې د صور څخه خپل سفر ته دوام ورکړ او د پتولاماییس ښار ته ورسېدلو. هلته مو د ایماندارانو سره ستړي مشي وکړه او د یوې ورځې دپاره د هغوی سره پاتې شولو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_7.mp3', '', 1761754199, 1761754199),
(32206, 'Acts 21:8', 'Acts', 21, 8, 'په بله ورځ له هغه ځای څخه روان شولو او قیصریې ته ورسېدلو او هلته د فیلیپوس په کور کې چې زېری رسوونکی ؤ، پاتې شولو. هغه د هغو اوو کسانو څخه ؤ چې په اورشلیم کې د خوړو د وېشلو دپاره ټاکل شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_8.mp3', '', 1761754199, 1761754199),
(32207, 'Acts 21:9', 'Acts', 21, 9, 'فیلیپوس څلور پېغلې لورګانې لرلې چې د خدای پیغام به یې رساوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_9.mp3', '', 1761754199, 1761754199),
(32208, 'Acts 21:10', 'Acts', 21, 10, 'کله چې مونږ څو ورځې هلته وو، نو د یهودیې څخه د اګابوس په نوم یو پیغمبر راغی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_10.mp3', '', 1761754199, 1761754199),
(32209, 'Acts 21:11', 'Acts', 21, 11, 'هغه مونږ ته راغی، د پولوس کمربند یې واخیست او په هغه باندې یې خپل لاسونه او پښې وتړلې او ویې ویل: «روح القدس داسې وایي: ‹په اورشلیم کې به یهودیان د دې کمربند خاوند همدا شان وتړي او غیریهودیانو ته به یې وسپاري.›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_11.mp3', '', 1761754199, 1761754199),
(32210, 'Acts 21:12', 'Acts', 21, 12, 'کله چې مو دا خبرې واورېدلې، نو مونږ او د هغه ځای خلکو پولوس ته زارۍ وکړې چې اورشلیم ته لاړ نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts21_verse_12.mp3', '', 1761754199, 1761754199);